import { formatPrice } from "@/utils/constants";
export const cop = (value) => `$ ${formatPrice(value)}`;
export const formatDate = (iso) => new Date(iso).toLocaleString("es-CO", {
    year: "numeric",
    day: "numeric",
    month: "numeric",
});
/**
 * `email_status`/`whatsapp_status` del backend traen texto interno para
 * depurar ("fallo: internal error; reference = ..."), no para mostrárselo al
 * negocio. Esto lo traduce a algo legible.
 */
export const notificationInfo = (status) => {
    if (status.startsWith("fallo"))
        return { label: "No llegó", variant: "block" };
    if (status === "enviado")
        return { label: "Enviado", variant: "done" };
    if (status === "pendiente")
        return { label: "Pendiente", variant: "wait" };
    if (status === "no_aplica")
        return { label: "No aplica", variant: "muted" };
    return { label: status, variant: "muted" };
};
/** ¿Alguna de las notificaciones falló? Sirve para marcar la fila en la lista. */
export const hasNotificationFailure = (...statuses) => statuses.some((status) => status === null || status === void 0 ? void 0 : status.startsWith("fallo"));
/** "12 pedido(s)", o "Mostrando 50 de 120" cuando la lista se recortó y hay que afinar la búsqueda. */
export const countLabel = (shown, total, noun) => shown < total
    ? `Mostrando ${shown} de ${total} ${noun} — afina la búsqueda para ver el resto`
    : `${total} ${noun}`;
